@Service
public class JpaUserDetailsService implements UserDetailsService {
    private final UserRepository repo;
    JpaUserDetailsService(UserRepository repo) { this.repo = repo; }

    @Override
    public UserDetails loadUserByUsername(String username) {
        User u = repo.findByUsername(username)
            .orElseThrow(() -> new UsernameNotFoundException(username));
        return org.springframework.security.core.userdetails.User
            .withUsername(u.getUsername())
            .password(u.getPasswordHash())          // BCrypt hash from DB
            .authorities("ROLE_" + u.getRole())
            .build();
    }
}

@Bean
PasswordEncoder passwordEncoder() {
    return new BCryptPasswordEncoder(); // DaoAuthenticationProvider uses this to verify
}
```
*You supply how to load a user and how to check the password; Spring orchestrates the rest.*

